import"./shimless_rma_shared.css.js";import"chrome://resources/cr_elements/cr_button/cr_button.js";import"chrome://resources/cr_elements/cr_dialog/cr_dialog.js";import{assertNotReached}from"chrome://resources/ash/common/assert.js";import{I18nBehavior,I18nBehaviorInterface}from"chrome://resources/ash/common/i18n_behavior.js";import{loadTimeData}from"chrome://resources/ash/common/load_time_data.m.js";import{mixinBehaviors,PolymerElement}from"chrome://resources/polymer/v3_0/polymer/polymer_bundled.min.js";import{getShimlessRmaService}from"./mojo_interface_provider.js";import{getTemplate}from"./shimless_3p_diagnostics.html.js";import{Shimless3pDiagnosticsAppInfo,ShimlessRmaServiceInterface,Show3pDiagnosticsAppResult}from"./shimless_rma.mojom-webui.js";import{disableAllButtons,enableAllButtons}from"./shimless_rma_util.js";const Shimless3pDiagnosticsBase=mixinBehaviors([I18nBehavior],PolymerElement);export class Shimless3pDiagnostics extends Shimless3pDiagnosticsBase{static get is(){return"shimless-3p-diagnostics"}static get template(){return getTemplate()}static get properties(){return{hasPendingLaunch:{type:Boolean,value:false},providerName:{type:String,value:""},installableAppPath:{type:String,value:""},appInfo:{type:Object,value:null},errorTitle:{type:String,value:""},errorMessage:{type:String,value:""}}}constructor(){super();if(!loadTimeData.getBoolean("3pDiagnosticsEnabled")){return}this.shimlessRmaService=getShimlessRmaService();this.shimlessRmaService.get3pDiagnosticsProvider().then((({provider:provider})=>{this.providerName=provider}))}completeLaunch(){this.hasPendingLaunch=false;enableAllButtons(this)}showError(titleId,messageId){this.errorTitle=this.i18n(titleId,this.providerName);this.errorMessage=this.i18n(messageId);this.root.querySelector("#shimless3pDiagErrorDialog").showModal()}showFindInstallableDialog(appPath){this.installableAppPath=appPath.path;this.root.querySelector("#shimless3pDiagFindInstallableDialog").showModal()}completeLastInstall(isApproved){this.shimlessRmaService.completeLast3pDiagnosticsInstallation(isApproved).then((()=>{isApproved?this.show3pDiagnosticsApp():this.completeLaunch()}))}showPermissionReviewDialogOrCompleteLastInstall(appInfo){if(!appInfo.permissionMessage){this.completeLastInstall(true);return}this.appInfo=appInfo;this.root.querySelector("#shimless3pDiagReviewPermissionDialog").showModal()}show3pDiagnosticsApp(){this.shimlessRmaService.show3pDiagnosticsApp().then((result=>{switch(result.result){case Show3pDiagnosticsAppResult.kOk:this.completeLaunch();return;case Show3pDiagnosticsAppResult.kAppNotInstalled:this.showError("3pNotInstalledDialogTitle","3pCheckWithOemDialogMessage");return;case Show3pDiagnosticsAppResult.kFailedToLoad:this.showError("3pFailedToLoadDialogTitle","3pFailedToLoadDialogMessage");return}assertNotReached()}))}onCancelOrSkipInstallButtonClicked(){this.shadowRoot.querySelector("#shimless3pDiagFindInstallableDialog").close();this.show3pDiagnosticsApp()}onInstallButtonClicked(){this.shadowRoot.querySelector("#shimless3pDiagFindInstallableDialog").close();this.shimlessRmaService.installLastFound3pDiagnosticsApp().then((result=>{result.appInfo?this.showPermissionReviewDialogOrCompleteLastInstall(result.appInfo):this.showError("3pFailedToInstallDialogTitle","3pCheckWithOemDialogMessage")}))}onCancelOrCancelInstallButtonClicked(){this.shadowRoot.querySelector("#shimless3pDiagReviewPermissionDialog").close();this.completeLastInstall(false)}onAcceptPermissionButtonClicked(){this.shadowRoot.querySelector("#shimless3pDiagReviewPermissionDialog").close();this.completeLastInstall(true)}onErrorDialogCancelOrBackButtonClicked(){this.shadowRoot.querySelector("#shimless3pDiagErrorDialog").close();this.completeLaunch()}launch3pDiagnostics(){if(!loadTimeData.getBoolean("3pDiagnosticsEnabled")||this.hasPendingLaunch){return}if(!this.providerName){return}this.hasPendingLaunch=true;disableAllButtons(this,true);this.shimlessRmaService.getInstallable3pDiagnosticsAppPath().then((result=>{result.appPath?this.showFindInstallableDialog(result.appPath):this.show3pDiagnosticsApp()}))}}customElements.define(Shimless3pDiagnostics.is,Shimless3pDiagnostics);